/* SANDSTAR title-art overlay P0; origin custom-domain Worker remains unchanged. */
const SS_STYLE="<style id=\"ssTitleArtStyles\">/* SANDSTAR TITLE ART P0: baked pixel artwork + live accessible HTML controls. */\n#startScreen.ss-start{--ss-aspect:1.777;--ss-inverse:.5627;position:absolute;overflow:hidden;background:#1b1735;}\n#startScreen.ss-start::before,#startScreen .ss-grain{display:none}\n#startScreen .ss-art-stage,#startScreen .ss-layout{\n  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);\n  width:min(100vw,calc(100dvh * var(--ss-aspect)));\n  height:min(100dvh,calc(100vw * var(--ss-inverse)));\n  max-width:none;min-height:0;max-height:none;margin:0;padding:0;\n}\n#startScreen .ss-art-stage{z-index:0;pointer-events:none;overflow:hidden}\n#startScreen .ss-art-stage picture,#startScreen .ss-title-picture{display:block;width:100%;height:100%}\n#startScreen .ss-title-picture{object-fit:fill;image-rendering:auto}\n#startScreen .ss-layout{z-index:1;display:block;pointer-events:none}\n#startScreen .ss-hero{position:absolute!important;width:1px!important;height:1px!important;overflow:hidden!important;clip-path:inset(50%)!important}\n#startScreen #ssMainPanel{position:absolute;inset:0;width:100%;height:100%;max-width:none;min-width:0;background:transparent;border:0;box-shadow:none;border-radius:0;padding:0;pointer-events:none}\n#startScreen #ssMainPanel::before{display:none}\n#startScreen #ssHome{position:absolute;inset:0;pointer-events:none}\n#startScreen #ssHome>:not(.ss-actions){position:absolute!important;width:1px!important;height:1px!important;overflow:hidden!important;clip-path:inset(50%)!important}\n#startScreen #ssHome .ss-actions{position:absolute;inset:0;display:block;pointer-events:none}\n#startScreen #ssHome .ss-duo{display:contents}\n#startScreen #ssHome #ssContinue,#startScreen #ssHome #ssNew,#startScreen #ssHome #ssSettings{\n  position:absolute;display:block;min-height:0;height:9.7%;width:20%;border:0!important;border-radius:8px;background:transparent!important;\n  box-shadow:none!important;padding:0!important;color:transparent!important;text-shadow:none!important;\n  font-size:0!important;line-height:0!important;cursor:pointer;pointer-events:auto;\n  transition:filter .12s,box-shadow .12s,background .12s;\n}\n#startScreen #ssHome #ssContinue * ,#startScreen #ssHome #ssNew *,#startScreen #ssHome #ssSettings *{visibility:hidden}\n#startScreen #ssHome #ssContinue{left:39.5%;top:50.3%}\n#startScreen #ssHome #ssNew{left:39.5%;top:61.1%;height:9.1%}\n#startScreen #ssHome #ssSettings{left:39.5%;top:71.2%;height:8.7%}\n#startScreen #ssHome #ssContinue:hover:not(:disabled),#startScreen #ssHome #ssNew:hover,#startScreen #ssHome #ssSettings:hover{\n  background:#ffda8240!important;box-shadow:inset 0 0 0 2px #ffe7a8,0 0 14px 3px #ffd37190!important\n}\n#startScreen #ssHome #ssContinue:focus-visible,#startScreen #ssHome #ssNew:focus-visible,#startScreen #ssHome #ssSettings:focus-visible{\n outline:3px solid #fff2bd;outline-offset:2px;box-shadow:0 0 0 5px #3d1d3d!important\n}\n#startScreen #ssHome #ssContinue:disabled{cursor:not-allowed;background:#211c2870!important;filter:grayscale(.5);opacity:1}\n#startScreen #ssHome #ssFullscreen,#startScreen #ssHome #ssBackup{\n  position:absolute;min-height:28px;width:auto;max-width:45%;pointer-events:auto;display:flex;justify-content:center;align-items:center;\n  background:#26182bc9;color:#f4ebd7;border:1px solid #e1bc7cb3;padding:7px 9px;font-size:11px;line-height:1.25;border-radius:6px;\n}\n#startScreen #ssHome #ssFullscreen{top:2%;right:2%;max-width:120px}\n#startScreen #ssHome #ssBackup{bottom:2%;left:2%;max-width:200px}\n#startScreen #ssHome #ssFullscreen:hover,#startScreen #ssHome #ssBackup:hover{background:#543243}\n#startScreen #ssMainPanel.ss-detail-open::before{display:block;content:\"\";position:fixed;inset:-100vh -100vw;background:#0b0c20c9;z-index:1;pointer-events:auto}\n#startScreen #ssMainPanel.ss-detail-open>.ss-view:not([hidden]){\n position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(520px,94vw);\n max-height:min(82dvh,760px);overflow:auto;padding:20px;z-index:2;pointer-events:auto;\n background:linear-gradient(160deg,#1a2c3cf8,#211f36f9);border:2px solid #dfba81;border-radius:10px;\n box-shadow:0 12px 0 #0d0a1b,0 22px 75px #000c;\n}\n#startScreen .ss-start-loader{z-index:35}\n@media (max-height:620px) and (orientation:landscape){\n #startScreen.ss-start{--ss-aspect:2.2235;--ss-inverse:.44973}\n #startScreen #ssHome #ssContinue{left:38.85%;top:50.75%;width:22.2%;height:11.3%}\n #startScreen #ssHome #ssNew{left:38.85%;top:62.75%;width:22.2%;height:10.4%}\n #startScreen #ssHome #ssSettings{left:38.85%;top:75.15%;width:22.2%;height:10.1%}\n #startScreen #ssHome #ssFullscreen{top:1%;right:1%;font-size:10px;min-height:23px}\n #startScreen #ssMainPanel.ss-detail-open>.ss-view:not([hidden]){max-height:94dvh;padding:11px 16px}\n}\n@media (orientation:portrait){\n #startScreen.ss-start{--ss-aspect:.5628;--ss-inverse:1.7768}\n #startScreen #ssHome #ssContinue{left:22.3%;top:64.5%;width:53.6%;height:7.2%}\n #startScreen #ssHome #ssNew{left:22.3%;top:72.55%;width:53.6%;height:6.7%}\n #startScreen #ssHome #ssSettings{left:22.3%;top:80.0%;width:53.6%;height:6.6%}\n #startScreen #ssHome #ssFullscreen{top:1.6%;right:3%;min-height:28px;max-width:85px;font-size:10px}\n #startScreen #ssHome #ssBackup{left:10%;bottom:1.1%;max-width:80%;font-size:10px}\n #startScreen #ssHome #ssFullscreen{right:auto;left:71%;max-width:75px;}\n #startScreen .ss-art-stage,#startScreen .ss-layout{width:max(100vw,calc(100dvh * .5628));height:max(100dvh,calc(100vw * 1.7768));}\n #startScreen #ssMainPanel.ss-detail-open>.ss-view:not([hidden]){max-height:85dvh;padding:15px}\n}\n@media (prefers-reduced-motion:reduce){#startScreen #ssHome .ss-btn{transition:none}}</style>";
const SS_ART="<div id=\"ssTitleArt\" class=\"ss-art-stage\" aria-hidden=\"true\"><picture><source media=\"(orientation:portrait)\" type=\"image/webp\" srcset=\"data:image/webp;base64,\"><source media=\"(max-height:620px) and (orientation:landscape)\" type=\"image/webp\" srcset=\"data:image/webp;base64,\"><img class=\"ss-title-picture\" src=\"data:image/webp;base64,\" alt=\"\" decoding=\"sync\" fetchpriority=\"high\"></picture></div>";
const SS_CLIENT="<script id=\"ssTitleArtSync\">(function(){function sync(){var p=document.getElementById('ssMainPanel'),h=document.getElementById('ssHome');if(p&&h)p.classList.toggle('ss-detail-open',!!h.hidden);}function start(){var h=document.getElementById('ssHome');if(!h)return;sync();new MutationObserver(sync).observe(h,{attributes:true,attributeFilter:['hidden']});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();})();</script>";
class SSHead{element(el){el.append(SS_STYLE,{html:true})}}
class SSStart{element(el){el.prepend(SS_ART,{html:true})}}
class SSBody{element(el){el.append(SS_CLIENT,{html:true})}}
async function ssHandle(request){
  const url=new URL(request.url);
  // Route only the exact homepage; /og-image.jpg, /robots.txt, /sitemap.xml etc remain on the original Worker.
  if(request.method!=='GET'||url.pathname!=='/') return fetch(request);
  // Cloudflare Worker Routes can fetch a Worker Custom Domain on the same hostname.
  const upstream=await fetch(request);
  const type=(upstream.headers.get('content-type')||'').toLowerCase();
  if(!upstream.ok||!type.includes('text/html')) return upstream;
  const headers=new Headers(upstream.headers);
  headers.delete('content-length');headers.delete('content-encoding');headers.delete('etag');
  headers.set('x-sandstar-title-art','20261118-p0');
  return new HTMLRewriter().on('head',new SSHead()).on('#startScreen',new SSStart()).on('body',new SSBody())
    .transform(new Response(upstream.body,{status:upstream.status,statusText:upstream.statusText,headers}));
}
addEventListener('fetch',event=>event.respondWith(ssHandle(event.request)));
